[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/ritofngmsTAPP-detail-P0> ;
            sh:resultMessage "Core requires schema:measurementTechnique on the analysis." ;
            sh:resultPath schema1:measurementTechnique ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "Core requires schema:measurementTechnique on the analysis." ;
                    sh:minCount 1 ;
                    sh:path schema1:measurementTechnique ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/ritofngmsTAPP-detail-P0> ;
            sh:resultMessage "Core requires schema:variableMeasured on the analysis." ;
            sh:resultPath schema1:variableMeasured ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "Core requires schema:variableMeasured on the analysis." ;
                    sh:minCount 1 ;
                    sh:path schema1:variableMeasured ;
                    sh:severity sh:Warning ] ] .

